		} else if (cmd == "project") { // select A from R
			project(&buf);
		} else if (cmd == "nlj") { // nested-loop-join
			nestedLoopJoin(&buf);
		} else if (cmd == "hj") { // hash-join
			hashJoin(&buf);
		} else if (cmd == "smj") { // sort-merge-join
			sortMergeJoin(&buf);
		}
		freeBuffer(&buf);
	}

	return 0;
}
